// One-off seed script: populates data/blogs.json with the 30 AHVI journal articles.
// Run with: node scripts/seed-blogs.js
const fs = require("fs");
const path = require("path");

// Local placeholder paths only — no images are generated, downloaded or hosted externally.
// Real files get uploaded manually to public/images/blog/ later under these exact filenames;
// the path is centralized here (not hardcoded per-component) so swapping files is a drop-in.
// Uploaded files live under public/images/blogs/ (plural) — matches the actual folder on disk.
function blogImagePath(index) {
  return `/images/blogs/blog-${String(index + 1).padStart(2, "0")}.jpg`;
}
function blogHeroPath(index) {
  return `/images/blogs/blog-${String(index + 1).padStart(2, "0")}-hero.jpg`;
}
function blogContentImagePaths(index, count = 3) {
  const n = String(index + 1).padStart(2, "0");
  return Array.from({ length: count }, (_, k) => `/images/blogs/blog-${n}-image-${String(k + 1).padStart(2, "0")}.jpg`);
}

function p(text) {
  return `<p>${text}</p>`;
}
function h2(text) {
  return `<h2>${text}</h2>`;
}
function ul(items) {
  return `<ul>${items.map((i) => `<li>${i}</li>`).join("")}</ul>`;
}
function quote(text) {
  return `<blockquote>${text}</blockquote>`;
}

function slugify(title) {
  return title
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

