const now = Date.now();

const blogs = POSTS.map((post, i) => {
  const slug = slugify(post.title);
  const createdAt = new Date(now - (POSTS.length - i) * 86400000).toISOString();
  return {
    id: "b_" + (now - (POSTS.length - i) * 1000).toString(36),
    title: post.title,
    slug,
    excerpt: post.excerpt,
    content: post.sections.join(""),
    coverImage: blogImagePath(i),
    heroImage: blogHeroPath(i),
    contentImages: blogContentImagePaths(i),
    shapeCarousels: post.shapeCarousels || undefined,
    galleryCarousel: post.galleryCarousel || undefined,
    category: post.category,
    author: "AHVI Team",
    readingTime: post.readingTime,
    featured: i === 0,
    tags: post.tags,
    status: "published",
    publishedAt: createdAt,
    createdAt,
    updatedAt: createdAt,
  };
});

// Blog 3 (Body Shape Guide) and Blog 4 (Your Style Persona) only need their cover image plus their
// own dedicated shape/persona carousels — no generic hero or interleaved content images.
[2, 3].forEach((i) => {
  delete blogs[i].heroImage;
  blogs[i].contentImages = [];
});

// Blog 27's cover file was uploaded as "bolg-27.jpg" (typo in the filename) instead of "blog-27.jpg" —
// point at the file that actually exists rather than a path that would 404.
blogs[26].coverImage = "/images/blogs/bolg-27.jpg";

// Blog 25 and Blog 26/29 have no uploaded images of their own — reuse Blog 10's and Blog 11's
// image sets respectively (per explicit request) rather than leaving them pointing at unuploaded files.
blogs[24].coverImage = blogs[9].coverImage;
blogs[24].heroImage = blogs[9].heroImage;
blogs[24].contentImages = blogs[9].contentImages;

blogs[25].coverImage = blogs[10].coverImage;
blogs[25].heroImage = blogs[10].heroImage;
blogs[25].contentImages = blogs[10].contentImages;

blogs[28].coverImage = blogs[10].coverImage;
blogs[28].heroImage = blogs[10].heroImage;
blogs[28].contentImages = blogs[10].contentImages;

// De-duplicate slugs (two source posts share the same "Men's Fashion Trends for Fall 2026" title)
const seen = {};
for (const b of blogs) {
  if (seen[b.slug]) {
    seen[b.slug] += 1;
    b.slug = b.slug + "-" + seen[b.slug];
  } else {
    seen[b.slug] = 1;
  }
}

const outPath = path.join(__dirname, "..", "data", "blogs.json");
fs.writeFileSync(outPath, JSON.stringify(blogs, null, 2), "utf8");
console.log(`Wrote ${blogs.length} blogs to ${outPath}`);
